static const float gripreset_tab[39] = {27.200000762939453f, 20.799999237060547f, 17.600000381469727f, 21.399999618530273f, 25.200000762939453f, 23.0f, 19.799999237060547f, 14.600000381469727f, 18.399999618530273f, 23.799999237060547f, 22.399999618530273f, 26.600000381469727f, 24.200000762939453f, 42.400001525878906f, 23.600000381469727f, 32.79999923706055f, 19.399999618530273f, 35.0f, 37.0f, 56.0f, 40.0f, 35.0f, 30.0f, 20.0f, 27.0f, 18.0f, 22.0f, 19.0f, 20.0f, 22.0f, 20.0f, 16.0f, 24.0f, 22.399999618530273f, 25.0f, 30.0f, 27.0f, 30.0f, 24.0f};

static double (*def_random)(void);
static double (*def_mrandom)(void);
static int32_t n_random, n_mrandom;
static double count_random(void) { n_random++; return def_random(); }
static double count_mrandom(void) { n_mrandom++; return def_mrandom(); }

static int failures;

static void setup(CareerRace *r, CareerSave *s, int32_t stage, int32_t bonus, bool hard, bool scale, bool nolev,
                  int32_t unlocked, int32_t nplayers, const int32_t *sc, uint32_t beast, uint32_t shadow,
                  int32_t plevel, const int32_t *psp, int32_t extp) {
  memset(r, 0, sizeof(*r));
  memset(s, 0, sizeof(*s));
  r->stage = stage;
  r->bonus = bonus;
  r->hardstage = hard;
  r->scalelevels = scale;
  r->nolevels = nolev;
  r->nplayers = nplayers;
  for (int g = 0; g < CAREER_MAX_PLAYERS; g++) {
    r->sc[g] = sc[g];
    r->beast[g] = (beast >> g) & 1u;
    r->shadow[g] = (shadow >> g) & 1u;
    r->level[g] = 1;  // Madness.level's initial value
  }
  r->level[0] = plevel;
  memcpy(r->sp[0], psp, sizeof(r->sp[0]));
  s->unlocked = unlocked;
  s->extpoints[sc[0]] = extp;
}

static bool run_and_check_draws(const char *what, int idx, CareerRace *r, CareerSave *s, uint32_t seed,
                                int32_t nrand, int32_t nmrand, uint32_t probe) {
  nfm_set_seed(seed);
  n_random = 0;
  n_mrandom = 0;
  career_airpgstats(r, s, gripreset_tab);
  bool ok = true;
  if (n_random != nrand || n_mrandom != nmrand) {
    printf("%s %d: draws random %d m.random %d, expected %d %d\n", what, idx, n_random, n_mrandom, nrand, nmrand);
    ok = false;
  }
  double next = nfm_random();
  if (next != probe / 4294967296.0) {
    printf("%s %d: stream after the case at %u, expected %u\n", what, idx, (uint32_t)(next * 4294967296.0), probe);
    ok = false;
  }
  return ok;
}

static void test_air_cases(void) {
  for (int i = 0; i < N_AIR_CASES; i++) {
    const AirCase *c = &air_cases[i];
    CareerRace r;
    CareerSave s;
    setup(&r, &s, c->stage, c->bonus, c->hard, c->scale, c->nolev, c->unlocked, c->nplayers, c->sc, c->beast,
          c->shadow, c->plevel, c->psp, c->extp);
    bool ok = run_and_check_draws("air case", i, &r, &s, c->seed, c->nrand, c->nmrand, c->probe);
    for (int g = 0; g < c->ncmp; g++) {
      if (r.level[g] != c->level[g]) {
        printf("air case %d (stage %d bonus %d): slot %d level %d, expected %d\n", i, c->stage, c->bonus, g,
               r.level[g], c->level[g]);
        ok = false;
      }
      for (int k = 0; k < CS_N; k++) {
        if (r.sp[g][k] != c->sp[g][k]) {
          printf("air case %d (stage %d bonus %d): slot %d car %d stat %d = %d, expected %d\n", i, c->stage,
                 c->bonus, g, c->sc[g], k, r.sp[g][k], c->sp[g][k]);
          ok = false;
        }
      }
    }
    if (r.softlevelcap != c->softcap || r.averagelevel != c->avg) {
      printf("air case %d: softlevelcap %d averagelevel %d, expected %d %d\n", i, r.softlevelcap, r.averagelevel,
             c->softcap, c->avg);
      ok = false;
    }
    if (!ok) failures++;
  }
}

static uint32_t fnv(uint32_t h, int32_t v) { return (h ^ (uint32_t)v) * 16777619u; }

static void test_sweep_cases(void) {
  for (int i = 0; i < N_SWEEP_CASES; i++) {
    const SweepCase *c = &sweep_cases[i];
    int32_t sc[CAREER_MAX_PLAYERS];
    uint32_t beast = 0, shadow = 0;
    sc[0] = c->psc;
    for (int g = 1; g < CAREER_MAX_PLAYERS; g++) {
      sc[g] = c->car;
      if (c->v == 1 ? g % 2 == 0 : g % 3 == 1) beast |= 1u << g;
      if (c->v == 1 ? g % 4 == 1 : g % 3 == 2) shadow |= 1u << g;
    }
    CareerRace r;
    CareerSave s;
    setup(&r, &s, c->stage, c->bonus, c->v == 1, c->v >= 2, false, c->unlocked, c->nplayers, sc, beast, shadow,
          c->plevel, c->psp, c->extp);
    bool ok = run_and_check_draws("sweep case", i, &r, &s, c->seed, c->nrand, c->nmrand, c->probe);
    uint32_t h = 0x811c9dc5u;
    for (int g = 0; g < c->ncmp; g++) {
      h = fnv(h, r.level[g]);
      for (int k = 0; k < CS_N; k++) h = fnv(h, r.sp[g][k]);
    }
    h = fnv(h, r.softlevelcap);
    h = fnv(h, r.averagelevel);
    if (h != c->hash) {
      printf("sweep case %d (stage %d bonus %d car %d setup %d): outputs differ (hash %08x, expected %08x)\n", i,
             c->stage, c->bonus, c->car, c->v, h, c->hash);
      ok = false;
    }
    if (!ok) failures++;
  }
}

static void test_formulas(void) {
  for (int32_t l = 0; l <= 130; l++) {
    if (career_spcalc(l) != spcalc_exp[l]) {
      printf("spcalc(%d) = %d, expected %d\n", l, career_spcalc(l), spcalc_exp[l]);
      failures++;
    }
    if (career_beastspcalc(l) != beastspcalc_exp[l]) {
      printf("beastspcalc(%d) = %d, expected %d\n", l, career_beastspcalc(l), beastspcalc_exp[l]);
      failures++;
    }
    for (int32_t car = 0; car < 39; car++) {
      if (career_reqneed(l, car) != reqneed_exp[car][l]) {
        printf("reqneed(%d, %d) = %d, expected %d\n", l, car, career_reqneed(l, car), reqneed_exp[car][l]);
        failures++;
      }
    }
  }
  for (int i = 0; i < N_HEALTH_CASES; i++) {
    const HealthCase *c = &health_cases[i];
    int32_t got = career_healthcalc(c->hp, c->sp, c->car, c->mod);
    if (got != c->expect) {
      printf("healthcalc(%d, %d, %d, %.9g) = %d, expected %d\n", c->hp, c->sp, c->car, c->mod, got, c->expect);
      failures++;
    }
  }
}

int main(void) {
  def_random = career_random;
  def_mrandom = career_mrandom;
  career_random = count_random;
  career_mrandom = count_mrandom;
  test_air_cases();
  test_sweep_cases();
  test_formulas();
  if (failures) {
    printf("%d failures\n", failures);
    return 1;
  }
  printf("all tests passed (%d lineups, %d sweep lineups, %d healthcalc, spcalc/beastspcalc/reqneed 0-130)\n",
         N_AIR_CASES, N_SWEEP_CASES, N_HEALTH_CASES);
  return 0;
}
